((SELECT id FROM m), 'Catering - American Flavors', 9, 'Wing Bar', 'Jumbo Wings tossed in your choice of wing sauce. Choose from: Traditional Buffalo, Asian Chili Honey, Garlic Jalapeno Butter, or Honey Habanero BBQ. Included sides of: Carrots, Celery, Ranch, Bleu Cheese, and Honey Dijon dipping sauces.', '$14.00/pp', 14.00, ARRAY[]::text[], 43),
